body{max-width:750px;margin:40px auto;padding:0 24px;font-family:'EB Garamond','Cormorant Garamond',Georgia,serif;font-size:1.15rem;line-height:1.85;color:#2c1810;background:#faf6f0;}

h1{font-family:'Cormorant Garamond',serif;font-size:2rem;text-align:center;margin-bottom:0.15em;color:#3a1f0f;}

h2{font-family:'Cormorant Garamond',serif;font-size:1.35rem;text-align:center;margin-top:0;color:#6b4226;}

.intro{font-style:italic;margin:1.5em 0;color:#5a3a1e;text-align:center;}

.section-heading{font-family:'Cormorant Garamond',serif;font-weight:600;font-size:1.2rem;color:#6b4226;margin-top:2.5em;margin-bottom:0.5em;border-bottom:1px solid #d4c4a8;padding-bottom:4px;}

.key-term{color:#5a3520;font-weight:inherit;}

.verse{font-style:italic;color:#4a2e14;}

.source{font-size:0.92em;color:#8a6e50;}

.gloss{font-size:0.92em;color:#6b4226;}

p{text-align:justify;margin:0.7em 0;}

.translator-summary{margin-top:3em;padding:1.5em;background:#f3ece0;border-radius:6px;border:1px solid #d4c4a8;}

.translator-summary h3{font-family:'Cormorant Garamond',serif;margin-top:0;color:#6b4226;}
